CREATE FUNCTION app_draft_version_immutable() RETURNS trigger
  LANGUAGE plpgsql SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF TG_OP = 'DELETE' THEN
        -- Only the cascade from a deleted draft (workspace erasure) may remove a version.
        IF EXISTS (SELECT 1 FROM draft d WHERE d.id = OLD.draft_id) THEN
          RAISE EXCEPTION 'draft_version % is immutable', OLD.id USING ERRCODE = 'insufficient_privilege';
        END IF;
        RETURN OLD;
      END IF;
      -- The one allowed change: nulling created_by when the author is erased.
      IF NEW.created_by IS NULL
        AND (to_jsonb(NEW) - 'created_by') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'created_by') THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'draft_version % is immutable', OLD.id USING ERRCODE = 'insufficient_privilege';
    END
  $$;--> statement-breakpoint
CREATE TRIGGER "draft_version_immutable" BEFORE UPDATE OR DELETE ON "draft_version"
  FOR EACH ROW EXECUTE FUNCTION app_draft_version_immutable();--> statement-breakpoint
REVOKE ALL ON FUNCTION app_draft_version_immutable() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_draft_version_immutable() TO causedeck_app;
